parameters.query:
SELECT coalesce(max(finished_at), now() - interval '2 days') AS since
FROM job_runs
WHERE job_name = 'calls_ingest' AND status = 'succeeded';

SELECT NOT EXISTS (
  SELECT 1 FROM interactions
  WHERE external_source = 'asterisk_drive' AND external_id = $1
) AS is_new;

